<?php require 'config/auth.php';$type=$_GET['type']??($_POST['type']??'student');if(!in_array($type,['student','company'],true))$type='student';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=trim($_POST['email']);$q=$pdo->prepare('SELECT id FROM users WHERE email=?');$q->execute([$email]);if($q->fetch())$err='Email already registered.';elseif($_POST['password']!==$_POST['confirm_password'])$err='Passwords do not match.';else{try{$pdo->beginTransaction();if($type==='student'){$name=trim($_POST['full_name']);$username=trim($_POST['roll_number']);$photo=upload('profile_photo','profiles',['jpg','jpeg','png','webp']);$resume=upload('resume','resumes',['pdf','doc','docx']);$u=$pdo->prepare("INSERT INTO users(role,name,email,username,password_hash,status) VALUES('student',?,?,?,?, 'active')");$u->execute([$name,$email,$username,password_hash($_POST['password'],PASSWORD_DEFAULT)]);$uid=$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO students(user_id,full_name,mobile,dob,gender,address,college,course,department,year,semester,roll_number,prn,cgpa,skills,certifications,profile_photo,resume) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$uid,$name,$_POST['mobile'],$_POST['dob']?:null,$_POST['gender'],$_POST['address'],$_POST['college'],$_POST['course'],$_POST['department'],$_POST['year'],$_POST['semester'],$_POST['roll_number'],$_POST['prn'],$_POST['cgpa']?:null,$_POST['skills'],$_POST['certifications'],$photo,$resume]);}else{$name=trim($_POST['company_name']);$logo=upload('company_logo','logos',['jpg','jpeg','png','webp']);$u=$pdo->prepare("INSERT INTO users(role,name,email,username,password_hash,status) VALUES('company',?,?,?,?, 'pending')");$u->execute([$name,$email,$email,password_hash($_POST['password'],PASSWORD_DEFAULT)]);$uid=$pdo->lastInsertId();$c=$pdo->prepare("INSERT INTO companies(user_id,company_name,company_email,contact_number,website,industry,address,hr_name,hr_email,description,logo,approval_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,'pending')");$c->execute([$uid,$name,$email,$_POST['contact'],$_POST['website'],$_POST['industry'],$_POST['address'],$_POST['hr_name'],$_POST['hr_email'],$_POST['description'],$logo]);}$pdo->commit();flash($type==='student'?'Student account created. You can login now.':'Company registration submitted. Admin approval is required.');go('login.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err='Registration failed. Please check your details.';}}}$page_title='Registration';require 'config/header.php';?><div class="auth"><div class="authleft"><div><span class="badge">JOIN CAREERBRIDGE</span><h1><?= $type==='student'?'Turn potential into opportunity.':'Build your campus hiring pipeline.'?></h1><p>Complete your details once and manage your placement journey from a professional dashboard.</p></div></div><div class="authright"><div class="authcard" style="max-height:90vh;overflow:auto"><h2><?=ucfirst($type)?> Registration</h2><p class="muted small">Fields marked * are required.</p><?php if($err):?><div class="flash error"><?=e($err)?></div><?php endif;?><div style="display:flex;gap:8px;margin-bottom:16px"><a class="btn <?=$type==='student'?'primary':'outline'?>" href="register.php">Student</a><a class="btn <?=$type==='company'?'primary':'outline'?>" href="register.php?type=company">Company</a></div><form method="post" enctype="multipart/form-data" class="form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="<?=e($type)?>"><?php if($type==='student'):?><div class="row"><div class="fg"><label>Full Name *</label><input class="control" name="full_name" required></div><div class="fg"><label>Email *</label><input class="control" type="email" name="email" required></div></div><div class="row"><div class="fg"><label>Mobile *</label><input class="control" name="mobile" required pattern="[0-9]{10}"></div><div class="fg"><label>Date of Birth</label><input class="control" type="date" name="dob"></div></div><div class="row"><div class="fg"><label>Gender</label><select class="control" name="gender"><option>Male</option><option>Female</option><option>Other</option></select></div><div class="fg"><label>College *</label><input class="control" name="college" required></div></div><div class="row"><div class="fg"><label>Course *</label><input class="control" name="course" required></div><div class="fg"><label>Department *</label><input class="control" name="department" required></div></div><div class="row"><div class="fg"><label>Year</label><select class="control" name="year"><option>FY</option><option>SY</option><option>TY</option></select></div><div class="fg"><label>Semester</label><input class="control" name="semester"></div></div><div class="row"><div class="fg"><label>Roll Number *</label><input class="control" name="roll_number" required></div><div class="fg"><label>PRN</label><input class="control" name="prn"></div></div><div class="row"><div class="fg"><label>CGPA</label><input class="control" name="cgpa" type="number" step=".01" min="0" max="10"></div><div class="fg"><label>Profile Photo</label><input class="control" name="profile_photo" type="file" accept=".jpg,.jpeg,.png,.webp"></div></div><div class="fg"><label>Address</label><textarea class="control" name="address"></textarea></div><div class="fg"><label>Skills</label><textarea class="control" name="skills" placeholder="PHP, MySQL, Python..."></textarea></div><div class="fg"><label>Certifications</label><textarea class="control" name="certifications"></textarea></div><div class="fg"><label>Resume</label><input class="control" name="resume" type="file" accept=".pdf,.doc,.docx"></div><?php else:?><div class="row"><div class="fg"><label>Company Name *</label><input class="control" name="company_name" required></div><div class="fg"><label>Company Email *</label><input class="control" type="email" name="email" required></div></div><div class="row"><div class="fg"><label>Contact *</label><input class="control" name="contact" required></div><div class="fg"><label>Website</label><input class="control" name="website" placeholder="https://"></div></div><div class="row"><div class="fg"><label>Industry</label><input class="control" name="industry"></div><div class="fg"><label>HR Name</label><input class="control" name="hr_name"></div></div><div class="row"><div class="fg"><label>HR Email</label><input class="control" type="email" name="hr_email"></div><div class="fg"><label>Logo</label><input class="control" name="company_logo" type="file" accept=".jpg,.jpeg,.png,.webp"></div></div><div class="fg"><label>Address</label><textarea class="control" name="address"></textarea></div><div class="fg"><label>Description</label><textarea class="control" name="description" rows="4"></textarea></div><?php endif;?><div class="row"><div class="fg"><label>Password *</label><input class="control" type="password" name="password" required minlength="6"></div><div class="fg"><label>Confirm Password *</label><input class="control" type="password" name="confirm_password" required></div></div><button class="btn primary" style="width:100%">Create Account →</button></form><p class="small muted center">Already registered? <a href="login.php" style="color:var(--p);font-weight:700">Login</a></p></div></div></div><?php require 'config/footer.php';?>
